-- Delete duplicates from reagents, keeping the one with highest quantity
-- First delete from the deduplicated table
DELETE FROM reagents_dedup;

-- Update to combine rows into single payload with newlines
UPDATE shared_export SET payload = (
  SELECT group_concat(payload || CHAR(13))
  FROM shared_export
  WHERE recipient_org = 'lab_inventory'
) WHERE recipient_org = 'lab_inventory';

DROP TABLE IF EXISTS reagents_dedup;

CREATE TABLE reagents_dedup AS
WITH dedup AS (
    SELECT r1.cas_number, r1.name, r1.quantity, r1.location, r1.lot_id, r1.notes
    FROM reagents r1
    WHERE (r1.cas_number, r1.quantity) IN (
        SELECT cas_number, MAX(quantity)
        FROM reagents
        GROUP BY cas_number
    )
)
SELECT * FROM dedup;
